function ScoreBadge({ type, value, size = 'md' }) {
  const isInspector = type === 'curator';
  const color = isInspector ? 'var(--gold)' : 'var(--indigo)';
  const bg = isInspector ? 'var(--gold-soft)' : 'var(--indigo-soft)';
  const Icon = isInspector ? Star : Gem;
  const pad = size === 'sm' ? '4px 8px' : size === 'lg' ? '9px 15px' : '6px 10px';
  const fs = size === 'sm' ? 12 : size === 'lg' ? 19 : 14;
  const iconSize = size === 'sm' ? 12 : size === 'lg' ? 19 : 14;
  return (
    <div
      className="atlas-display press"
      style={{
        display: 'inline-flex', alignItems: 'center', gap: size === 'lg' ? 7 : 5,
        background: bg, color, borderRadius: 999, padding: pad,
        fontSize: fs, fontWeight: 700, lineHeight: 1,
      }}
      title={isInspector ? 'Оценка инспектора' : 'Оценка игроков'}
    >
      <Icon size={iconSize} strokeWidth={2.5} fill={color} style={{ opacity: 0.9 }} />
      {value.toFixed(1)}
    </div>
  );
}

function Segmented({ options, value, onChange }) {
  return (
    <div style={{ background: 'var(--surface-2)', borderRadius: 999, padding: 3, display: 'flex', gap: 2 }}>
      {options.map((opt) => {
        const active = opt.value === value;
        return (
          <button
            key={opt.value}
            onClick={() => onChange(opt.value)}
            className="press"
            style={{
              display: 'flex', alignItems: 'center', gap: 6,
              padding: '7px 14px', borderRadius: 999, fontSize: 13, fontWeight: 600,
              border: 'none', cursor: 'pointer',
              background: active ? 'var(--indigo)' : 'transparent',
              color: active ? '#fff' : 'var(--text-muted)',
            }}
          >
            {opt.icon}{opt.label}
          </button>
        );
      })}
    </div>
  );
}

