// Full-screen viewer for a screenshot. Tap the image to toggle a closer zoom;
// on real phones this sits inside a scrollable frame so native pinch-zoom
// also works. In "moderate" mode the owner gets approve/reject actions here.
function Lightbox({ shot, mode, onClose, onApprove, onReject }) {
  const [zoomed, setZoomed] = useState(false);
  return (
    <div
      onClick={onClose}
      style={{
        position: 'fixed', inset: 0, background: 'rgba(6,7,9,0.95)', zIndex: 80,
        display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: 20,
      }}
    >
      <button onClick={onClose} className="press" style={{ ...iconBtn('var(--surface-2)', 'var(--text)'), position: 'absolute', top: 16, right: 16 }}>
        <X size={18} />
      </button>

      <div
        onClick={(e) => e.stopPropagation()}
        style={{ width: '100%', maxWidth: 448, maxHeight: '70vh', overflow: 'auto', borderRadius: 16, touchAction: 'pinch-zoom' }}
      >
        {shot.url ? (
          <img
            src={shot.url}
            alt={shot.author}
            onClick={() => setZoomed((z) => !z)}
            style={{
              width: '100%', display: 'block', cursor: zoomed ? 'zoom-out' : 'zoom-in',
              transform: zoomed ? 'scale(2.1)' : 'scale(1)', transformOrigin: 'center top', transition: 'transform .2s ease',
            }}
          />
        ) : (
          <div style={{
            width: '100%', aspectRatio: '4/3', background: 'var(--surface)', borderRadius: 16,
            display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-muted)',
          }}>
            <Camera size={32} />
          </div>
        )}
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 11, color: 'var(--text-muted)', marginTop: 10 }}>
        <ZoomIn size={12} /> Нажмите на фото, чтобы приблизить · от {shot.author}
      </div>

      {mode === 'moderate' && (
        <div style={{ display: 'flex', gap: 10, marginTop: 16, width: '100%', maxWidth: 448 }} onClick={(e) => e.stopPropagation()}>
          <button onClick={onApprove} className="press" style={{
            flex: 1, padding: '12px 0', borderRadius: 12, border: 'none', cursor: 'pointer',
            background: 'var(--emerald)', color: '#04140C', fontWeight: 700, fontSize: 14,
          }}>Одобрить</button>
          <button onClick={onReject} className="press" style={{
            flex: 1, padding: '12px 0', borderRadius: 12, border: 'none', cursor: 'pointer',
            background: 'var(--red-soft)', color: 'var(--red)', fontWeight: 700, fontSize: 14,
          }}>Отклонить</button>
        </div>
      )}
    </div>
  );
}

