// ---------------------------------------------------------------------------
// Interactive Vox map
// ---------------------------------------------------------------------------
function VoxMap({ image, territories, onSelect }) {
  const viewportRef = useRef(null);
  const pointersRef = useRef(new Map());
  const transformRef = useRef({ x: 0, y: 0, scale: 1 });
  const gestureRef = useRef(null);
  const [, forceRender] = useState(0);

  function applyTransform(next) {
    const clamped = { ...next, scale: Math.min(4, Math.max(1, next.scale)) };
    transformRef.current = clamped;
    forceRender((v) => v + 1);
  }

  function distance(a, b) {
    return Math.hypot(a.x - b.x, a.y - b.y);
  }

  function midpoint(a, b) {
    return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
  }

  function onPointerDown(e) {
    e.currentTarget.setPointerCapture?.(e.pointerId);
    pointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    const points = [...pointersRef.current.values()];
    const t = transformRef.current;
    if (points.length === 2) {
      const center = midpoint(points[0], points[1]);
      gestureRef.current = {
        mode: 'pinch',
        startDistance: distance(points[0], points[1]),
        startScale: t.scale,
        startX: t.x,
        startY: t.y,
        startCenter: center,
      };
    } else if (points.length === 1) {
      gestureRef.current = { mode: 'pan', startX: t.x, startY: t.y, pointer: points[0] };
    }
  }

  function onPointerMove(e) {
    if (!pointersRef.current.has(e.pointerId)) return;
    pointersRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    const points = [...pointersRef.current.values()];
    const g = gestureRef.current;
    if (!g) return;
    if (points.length >= 2 && g.mode === 'pinch') {
      const d = distance(points[0], points[1]);
      const c = midpoint(points[0], points[1]);
      const ratio = g.startDistance ? d / g.startDistance : 1;
      const scale = Math.min(4, Math.max(1, g.startScale * ratio));
      const dx = c.x - g.startCenter.x;
      const dy = c.y - g.startCenter.y;
      applyTransform({ scale, x: g.startX + dx, y: g.startY + dy });
    } else if (points.length === 1 && g.mode === 'pan') {
      const p = points[0];
      applyTransform({ scale: transformRef.current.scale, x: g.startX + p.x - g.pointer.x, y: g.startY + p.y - g.pointer.y });
    }
  }

  function onPointerUp(e) {
    pointersRef.current.delete(e.pointerId);
    const points = [...pointersRef.current.values()];
    if (points.length === 0) gestureRef.current = null;
    else if (points.length === 1) {
      const t = transformRef.current;
      gestureRef.current = { mode: 'pan', startX: t.x, startY: t.y, pointer: points[0] };
    }
  }

  function reset() {
    applyTransform({ x: 0, y: 0, scale: 1 });
  }

  const t = transformRef.current;
  return (
    <div
      ref={viewportRef}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      style={{
        position: 'relative', width: '100%', height: '100%', overflow: 'hidden', background: '#000',
        touchAction: 'none', userSelect: 'none', cursor: t.scale > 1 ? 'grab' : 'default',
      }}
    >
      <div style={{
        position: 'absolute', inset: 0,
        transform: `translate(${t.x}px, ${t.y}px) scale(${t.scale})`,
        transformOrigin: 'center center',
      }}>
        <img
          src={image}
          alt="Карта Vox"
          draggable={false}
          style={{
            position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'contain',
            pointerEvents: 'none', maxWidth: 'none', maxHeight: 'none',
          }}
        />
        {territories.map((city) => (
          <button
            key={city.id}
            onClick={() => onSelect(city.id)}
            className="press"
            style={{
              position: 'absolute', left: `${city.x}%`, top: `${city.y}%`, transform: 'translate(-50%,-50%)',
              border: 'none', background: 'transparent', cursor: 'pointer', padding: 8,
            }}
            title={city.name}
          >
            <span style={{ position: 'relative', display: 'block', width: 14, height: 14 }}>
              <span className="pin-pulse" style={{ position: 'absolute', inset: 0, borderRadius: '50%', background: city.accent }} />
              <span style={{ position: 'absolute', inset: 0, borderRadius: '50%', background: city.accent, border: '2px solid var(--bg)' }} />
            </span>
          </button>
        ))}
      </div>
      <button onClick={reset} className="press" style={{
        position: 'absolute', right: 10, top: 10, border: '1px solid rgba(255,255,255,.15)',
        background: 'rgba(11,13,16,.72)', color: '#fff', borderRadius: 10, padding: '6px 9px',
        fontSize: 11, cursor: 'pointer', backdropFilter: 'blur(8px)',
      }}>Сбросить</button>
    </div>
  );
}

function compressMapFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const max = 2048;
        const ratio = Math.min(1, max / Math.max(img.width, img.height));
        const canvas = document.createElement('canvas');
        canvas.width = Math.max(1, Math.round(img.width * ratio));
        canvas.height = Math.max(1, Math.round(img.height * ratio));
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/webp', 0.9));
      };
      img.onerror = reject;
      img.src = reader.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function MainInspectorPanel({ initData, onMapSaved }) {
  const [inspectors, setInspectors] = useState([]);
  const [telegramId, setTelegramId] = useState('');
  const [username, setUsername] = useState('');
  const [loading, setLoading] = useState(true);
  const [savingInspector, setSavingInspector] = useState(false);
  const [mapSaving, setMapSaving] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const fileRef = useRef(null);

  async function loadInspectors() {
    try {
      setLoading(true);
      const res = await fetch(`${API_BASE}/api/inspectors/list`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ initData }), cache: 'no-store',
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || !data.ok) throw new Error(data.error || `HTTP ${res.status}`);
      setInspectors(Array.isArray(data.inspectors) ? data.inspectors : []);
      setError('');
    } catch (e) {
      setError(e?.message || 'Не удалось загрузить список инспекторов');
    } finally { setLoading(false); }
  }

  useEffect(() => { if (initData) loadInspectors(); }, [initData]);

  async function add() {
    const id = telegramId.trim();
    if (!/^\d+$/.test(id)) { setError('Введите корректный Telegram ID.'); return; }
    try {
      setSavingInspector(true); setError('');
      const res = await fetch(`${API_BASE}/api/inspectors`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ initData, telegramId: id, username: username.trim() }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || !data.ok) throw new Error(data.error || `HTTP ${res.status}`);
      setTelegramId(''); setUsername(''); setNotice('Инспектор добавлен');
      await loadInspectors();
    } catch (e) { setError(e?.message || 'Не удалось добавить инспектора'); }
    finally { setSavingInspector(false); }
  }

  async function remove(id) {
    if (!window.confirm('Удалить этого инспектора?')) return;
    try {
      setError('');
      const res = await fetch(`${API_BASE}/api/inspectors/${id}`, {
        method: 'DELETE', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ initData }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || !data.ok) throw new Error(data.error || `HTTP ${res.status}`);
      setNotice('Инспектор удалён');
      await loadInspectors();
    } catch (e) { setError(e?.message || 'Не удалось удалить инспектора'); }
  }

  async function saveMap(file) {
    if (!file) return;
    try {
      setMapSaving(true); setError('');
      const mapImage = await compressMapFile(file);
      const res = await fetch(`${API_BASE}/api/map`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ initData, mapImage }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || !data.ok) throw new Error(data.error || `HTTP ${res.status}`);
      setNotice('Карта Vox обновлена');
      onMapSaved(mapImage);
    } catch (e) { setError(e?.message || 'Не удалось сохранить карту'); }
    finally { setMapSaving(false); if (fileRef.current) fileRef.current.value = ''; }
  }

  return (
    <div style={{ marginTop: 12 }}>
      <div style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 16, padding: 16, marginBottom: 12 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
          <Users size={16} color="var(--gold)" />
          <div className="atlas-display" style={{ fontSize: 16, fontWeight: 700 }}>Инспекторы</div>
          <span style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--text-muted)' }}>{inspectors.length}</span>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: 8, marginBottom: 12 }}>
          <input value={telegramId} onChange={(e) => setTelegramId(e.target.value.replace(/\D/g, ''))} placeholder="Telegram ID" inputMode="numeric" style={{ background:'var(--surface-2)', border:'1px solid var(--border)', borderRadius:10, padding:'10px 12px', color:'var(--text)', outline:'none' }} />
          <input value={username} onChange={(e) => setUsername(e.target.value)} placeholder="@username (необязательно)" style={{ background:'var(--surface-2)', border:'1px solid var(--border)', borderRadius:10, padding:'10px 12px', color:'var(--text)', outline:'none' }} />
          <button onClick={add} disabled={savingInspector} className="press" style={{ border:'none', borderRadius:10, padding:'10px 12px', background:'var(--gold)', color:'#1A1300', fontWeight:700, cursor:'pointer' }}>{savingInspector ? 'Добавление…' : 'Добавить инспектора'}</button>
        </div>
        {loading ? <div style={{ fontSize:12, color:'var(--text-muted)' }}>Загрузка…</div> : inspectors.length === 0 ? <div style={{ fontSize:12, color:'var(--text-muted)' }}>Инспекторов пока нет.</div> : inspectors.map((item) => (
          <div key={item.telegram_id} style={{ display:'flex', alignItems:'center', gap:10, padding:'10px 0', borderTop:'1px solid var(--border)' }}>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontSize:13, fontWeight:600 }}>{item.telegram_username ? `@${String(item.telegram_username).replace(/^@/,'')}` : 'Username не указан'}</div>
              <div style={{ fontSize:11, color:'var(--text-muted)', marginTop:2 }}>Telegram ID: {item.telegram_id}</div>
            </div>
            <button onClick={() => remove(item.telegram_id)} className="press" style={{ border:'none', background:'var(--red-soft)', color:'var(--red)', borderRadius:10, padding:'8px 10px', cursor:'pointer' }}><Trash2 size={14} /></button>
          </div>
        ))}
      </div>

      <div style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 16, padding: 16 }}>
        <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:8 }}><MapIcon size={16} color="var(--gold)" /><div className="atlas-display" style={{ fontSize:16, fontWeight:700 }}>Карта Vox</div></div>
        <div style={{ fontSize:12, color:'var(--text-muted)', lineHeight:1.5, marginBottom:10 }}>Загрузите новое изображение второй карты. Оно станет доступно всем пользователям после сохранения.</div>
        <input ref={fileRef} type="file" accept="image/*" style={{ display:'none' }} onChange={(e) => saveMap(e.target.files?.[0])} />
        <button onClick={() => fileRef.current?.click()} disabled={mapSaving} className="press" style={{ width:'100%', border:'none', borderRadius:10, padding:'10px 12px', background:'var(--indigo)', color:'#fff', fontWeight:700, cursor:'pointer' }}>{mapSaving ? 'Сохранение…' : 'Заменить карту Vox'}</button>
      </div>
      {notice && <div style={{ fontSize:12, color:'var(--emerald)', marginTop:8 }}>{notice}</div>}
      {error && <div style={{ fontSize:12, color:'var(--red)', marginTop:8 }}>{error}</div>}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Profile screen
// ---------------------------------------------------------------------------
function ProfileScreen({ profile, claimNickname, role, tgUser, refreshProfile }) {
  const isInspector = role === 'inspector' || role === 'main_inspector';
  const isMainInspector = role === 'main_inspector';
  const initData = window.Telegram?.WebApp?.initData || '';
  const [draft, setDraft] = useState(profile.nickname || '');
  const [error, setError] = useState('');

  useEffect(() => {
    setDraft(profile.nickname || '');
  }, [profile.nickname]);

  async function submit() {
    const res = await claimNickname(draft);
    setError(res.ok ? '' : res.message);
  }

  return (
    <div style={{ padding: '18px 16px 40px', minHeight: '60vh' }}>
      <div className="atlas-display" style={{ fontSize: 22, fontWeight: 700, marginBottom: 4 }}>Профиль</div>
      <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 20 }}>
        Ник нужен, чтобы выставлять оценки и оставлять отзывы под своим именем.
      </div>

      <div style={{
        background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 16, padding: 16, marginBottom: 12,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 14 }}>
          <AvatarHead nickname={profile.status === 'verified' ? profile.nickname : null} size={46} />
          <div>
            <div style={{ fontSize: 15, fontWeight: 600 }}>{profile.nickname || 'Ник не указан'}</div>
            {isInspector ? (
              <div style={{ fontSize: 11.5, color: 'var(--gold)', display: 'flex', alignItems: 'center', gap: 4, fontWeight: 700 }}>
                <ShieldCheck size={12} /> {isMainInspector ? 'Главный инспектор' : 'Инспектор'}
              </div>
            ) : profile.status === 'verified' ? (
              <div style={{ fontSize: 11.5, color: 'var(--emerald)', display: 'flex', alignItems: 'center', gap: 4 }}>
                <ShieldCheck size={12} /> Ник подтверждён
              </div>
            ) : profile.status === 'pending' ? (
              <div style={{ fontSize: 11.5, color: 'var(--gold)', display: 'flex', alignItems: 'center', gap: 4 }}>
                <Clock size={12} /> Ожидает подтверждения инспектора
              </div>
            ) : (
              <div style={{ fontSize: 11.5, color: 'var(--text-muted)' }}>Ник в Minecraft</div>
            )}
          </div>
        </div>

        <div style={{ fontSize: 11.5, color: 'var(--text-muted)', marginBottom: 10 }}>
          Telegram: {tgUser ? `@${tgUser.username || '—'} · id ${tgUser.id}` : 'не определён (открыто вне Telegram)'}
        </div>

        {!isInspector && profile.status !== 'verified' && (
          <>
            <div style={{ display: 'flex', gap: 8 }}>
              <input
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                placeholder="Ваш ник в Minecraft"
                style={{
                  flex: 1, background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 10,
                  padding: '10px 12px', color: 'var(--text)', fontSize: 13, outline: 'none',
                }}
              />
              <button onClick={submit} className="press" style={iconBtn('var(--indigo)', '#fff', true)}>
                <Pencil size={15} />
              </button>
            </div>
            {error && <div style={{ fontSize: 12, color: 'var(--red)', marginTop: 8 }}>{error}</div>}
          </>
        )}
      </div>

      {isMainInspector && <MainInspectorPanel initData={initData} onMapSaved={() => {}} />}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Home screen — Multi-Punk
// ---------------------------------------------------------------------------
function HomeScreen({ territories, onSelect, onAddTerritory, mode = 'map', mapImage = DEFAULT_VOX_MAP_IMAGE, onMapToast }) {
  const [sortBy, setSortBy] = useState('curator');
  const [mapMode, setMapMode] = useState('jorick');
  const sortedList = [...territories].sort((a, b) => b[sortBy] - a[sortBy]);
  const isVox = mapMode === 'vox';

  function toggleMap() {
    const next = isVox ? 'jorick' : 'vox';
    setMapMode(next);
    onMapToast?.(next === 'vox' ? 'Карта Vox' : 'Карта JORICK404');
  }

  return (
    <div style={{ paddingBottom: 90 }}>
      {mode === 'map' ? (
        <div style={{ padding: '0 16px' }}>
          <div style={{ position:'relative', width:'100%', aspectRatio:'1 / 1', borderRadius:6, border:'1px solid var(--border)', overflow:'hidden', background:'#000' }}>
            {isVox ? (
              <VoxMap image={mapImage} territories={territories} onSelect={onSelect} />
            ) : (
              <div style={{ position:'relative', width:'100%', height:'100%', backgroundImage:`url(${MAP_IMAGE})`, backgroundSize:'cover', backgroundPosition:'center' }}>
                <div style={{ position:'absolute', inset:0, background:'linear-gradient(180deg, rgba(11,13,16,0.15), rgba(11,13,16,0.05) 30%, rgba(11,13,16,0.25))' }} />
                {territories.map((t) => (
                  <button key={t.id} onClick={() => onSelect(t.id)} className="press" style={{ position:'absolute', left:`${t.x}%`, top:`${t.y}%`, transform:'translate(-50%,-50%)', border:'none', background:'transparent', cursor:'pointer', padding:8 }} title={t.name}>
                    <span style={{ position:'relative', display:'block', width:14, height:14 }}>
                      <span className="pin-pulse" style={{ position:'absolute', inset:0, borderRadius:'50%', background:t.accent }} />
                      <span style={{ position:'absolute', inset:0, borderRadius:'50%', background:t.accent, border:'2px solid var(--bg)' }} />
                    </span>
                  </button>
                ))}
              </div>
            )}
          </div>
          <div style={{ display:'flex', alignItems:'center', justifyContent:'center', gap:10, paddingTop:12 }}>
            <button onClick={toggleMap} className="press" aria-label={isVox ? 'Переключить на карту JORICK404' : 'Переключить на карту Vox'} style={{ width:62, height:62, padding:0, border:'1px solid var(--border)', borderRadius:14, overflow:'hidden', background:'var(--surface)', cursor:'pointer', boxShadow:'0 8px 24px rgba(0,0,0,.22)' }}>
              <img src={isVox ? MAP_SWITCH_IMAGE_VOX : MAP_SWITCH_IMAGE_JORICK} alt="Переключить карту" draggable={false} style={{ width:'100%', height:'100%', objectFit:'cover', display:'block' }} />
            </button>
          </div>
        </div>
      ) : (
        <div style={{ padding:'0 16px' }}>
          <div style={{ marginBottom:10 }}>
            <Segmented value={sortBy} onChange={setSortBy} options={[{ value:'curator', label:'По инспектору' }, { value:'community', label:'По игрокам' }]} />
          </div>
          {sortedList.length === 0 ? (
            <div style={{ textAlign:'center', padding:'40px 16px', color:'var(--text-muted)', fontSize:13 }}>Городов пока нет — станьте первым, кто добавит свой.</div>
          ) : (
            <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
              {sortedList.map((t, i) => (
                <button key={t.id} onClick={() => onSelect(t.id)} className="press" style={{ display:'flex', alignItems:'center', gap:12, textAlign:'left', background:'var(--surface)', border:'1px solid var(--border)', borderRadius:16, padding:10, cursor:'pointer', color:'var(--text)' }}>
                  <span className="atlas-display" style={{ width:20, fontSize:13, color:'var(--text-muted)', fontWeight:600 }}>{i + 1}</span>
                  <span style={{ width:46, height:46, borderRadius:12, flexShrink:0, background:`linear-gradient(135deg, ${t.accent}55, ${t.accent}15)`, border:`1px solid ${t.accent}55` }} />
                  <div style={{ flex:1, minWidth:0 }}><div className="atlas-display" style={{ fontSize:14, fontWeight:600 }}>{t.name}</div><div style={{ fontSize:12, color:'var(--text-muted)' }}>{t.owner} · {t.votes} оценок</div></div>
                  {sortBy === 'curator' ? <ScoreBadge type="curator" value={t.curator} size="lg" /> : <ScoreBadge type="community" value={t.community} size="lg" />}
                </button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Territory detail
// ---------------------------------------------------------------------------
function TerritoryDetail({ base, onBack, profile, onGoToProfile }) {
  const [t, setT] = useState(base);

  const hasNickname = profile.status === 'pending' || profile.status === 'verified';
  const isOwner = profile.status === 'verified' && profile.nickname.trim().toLowerCase() === t.owner.trim().toLowerCase();
  const isResident = !isOwner && hasNickname && t.residents.some((r) => r.trim().toLowerCase() === profile.nickname.trim().toLowerCase());

  const [ratedToday, setRatedToday] = useState(false);
  const [myRating, setMyRating] = useState({ integrity: 3, comfort: 3, atmosphere: 3, detail: 3 });
  const [reacted, setReacted] = useState({});
  const [newComment, setNewComment] = useState('');
  const [showResidents, setShowResidents] = useState(false);
  const [newResident, setNewResident] = useState('');
  const [toast, setToast] = useState(null);
  const [curatorRequested, setCuratorRequested] = useState(false);
  const [lightbox, setLightbox] = useState(null); // { shot, mode: 'view' | 'moderate' }
  const fileInputRef = useRef(null);

  function flash(msg) {
    setToast(msg);
    setTimeout(() => setToast(null), 2200);
  }

  function saveRating() {
    setRatedToday(true);
    flash('Оценка сохранена — обновится в общем рейтинге сегодня');
  }

  function react(reviewId, kind) {
    setReacted((prev) => {
      const current = prev[reviewId];
      if (kind === 'report') {
        flash('Жалоба отправлена инспектору');
        return { ...prev, [reviewId]: current === 'reported' ? current : 'reported' };
      }
      const already = current === kind;
      setT((prevT) => ({
        ...prevT,
        reviews: prevT.reviews.map((r) => {
          if (r.id !== reviewId) return r;
          const likes = r.likes + (kind === 'like' ? (already ? -1 : current === 'dislike' ? 1 : 1) : current === 'like' ? -1 : 0);
          const dislikes = r.dislikes + (kind === 'dislike' ? (already ? -1 : current === 'like' ? 1 : 1) : current === 'dislike' ? -1 : 0);
          return { ...r, likes, dislikes };
        }),
      }));
      return { ...prev, [reviewId]: already ? null : kind };
    });
  }

  function addComment() {
    if (!newComment.trim() || !hasNickname) return;
    setT((prev) => ({
      ...prev,
      reviews: [{ id: `r${Date.now()}`, author: profile.nickname, text: newComment.trim(), likes: 0, dislikes: 0, reply: null }, ...prev.reviews],
    }));
    setNewComment('');
    flash('Отзыв опубликован');
  }

  function reply(reviewId, text) {
    setT((prev) => ({ ...prev, reviews: prev.reviews.map((r) => (r.id === reviewId ? { ...r, reply: text } : r)) }));
  }

  function moderateShot(id, approve) {
    setT((prev) => ({
      ...prev,
      screenshots: prev.screenshots.map((s) => (s.id === id ? { ...s, status: approve ? 'approved' : 'rejected' } : s)),
    }));
    flash(approve ? 'Скрин добавлен в галерею' : 'Скрин перемещён в отклонённые');
    setLightbox(null);
  }

  function handleFilePicked(e) {
    const file = e.target.files && e.target.files[0];
    e.target.value = '';
    if (!file) return;
    const url = URL.createObjectURL(file);
    setT((prev) => ({
      ...prev,
      screenshots: [...prev.screenshots, { id: `s${Date.now()}`, author: profile.nickname || 'Гость', status: 'pending', url }],
    }));
    flash('Скрин отправлен на модерацию владельцу');
  }

  function addResident() {
    if (!newResident.trim()) return;
    setT((prev) => ({ ...prev, residents: [...prev.residents, newResident.trim()] }));
    setNewResident('');
  }

  function removeResident(name) {
    setT((prev) => ({ ...prev, residents: prev.residents.filter((r) => r !== name) }));
  }

  const approved = t.screenshots.filter((s) => s.status === 'approved');
  const pending = t.screenshots.filter((s) => s.status === 'pending');

  return (
    <div style={{ paddingBottom: 90, position: 'relative' }}>
      <div style={{
        position: 'relative', height: 150,
        background: `linear-gradient(160deg, ${t.accent}66, var(--surface) 85%)`,
      }}>
        <button
          onClick={onBack}
          className="press"
          style={{
            position: 'absolute', top: 14, left: 14, width: 34, height: 34, borderRadius: '50%',
            background: 'rgba(11,13,16,0.55)', border: '1px solid var(--border)', color: 'var(--text)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
          }}
        >
          <ChevronLeft size={18} />
        </button>
        <div style={{ position: 'absolute', bottom: 14, left: 16, right: 16 }}>
          <div className="atlas-display" style={{ fontSize: 24, fontWeight: 700 }}>{t.name}</div>
          <div style={{ fontSize: 13, color: 'rgba(237,238,242,0.75)' }}>
            Основатель/мэр: {t.owner}{t.coords ? <span style={{ color: 'rgba(237,238,242,0.5)' }}> · {t.coords}</span> : null}
          </div>
        </div>
      </div>

      <div style={{ padding: '14px 16px 0' }}>
        <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
          <ScoreBadge type="curator" value={t.curator} />
          <ScoreBadge type="community" value={t.community} />
        </div>

        <SectionTitle icon={<Camera size={15} />} title="Скрины" count={approved.length} />
        <div className="atlas-scroll" style={{ display: 'flex', gap: 8, overflowX: 'auto', paddingBottom: 4, marginBottom: 6 }}>
          {approved.map((s) => (
            <ShotThumb key={s.id} shot={s} onOpen={() => setLightbox({ shot: s, mode: 'view' })} />
          ))}
          {!isOwner && (
            <>
              <input ref={fileInputRef} type="file" accept="image/*" style={{ display: 'none' }} onChange={handleFilePicked} />
              <button
                onClick={() => fileInputRef.current && fileInputRef.current.click()}
                className="press"
                style={{
                  flexShrink: 0, width: 96, height: 68, borderRadius: 12, cursor: 'pointer',
                  border: '1px dashed var(--border)', background: 'transparent', color: 'var(--text-muted)',
                  display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 4, fontSize: 11,
                }}
              >
                <Plus size={16} /> Добавить
              </button>
            </>
          )}
        </div>

        <button
          onClick={() => setShowResidents(true)}
          className="press"
          style={{
            width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between',
            background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 14,
            padding: '12px 14px', margin: '14px 0', cursor: 'pointer', color: 'var(--text)',
          }}
        >
          <span style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 14, fontWeight: 600 }}>
            <Users size={16} color="var(--text-muted)" /> Жители
          </span>
          <span style={{ fontSize: 13, color: 'var(--text-muted)' }}>{t.residents.length} →</span>
        </button>

        {!isOwner && (
          <div style={{
            background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 16, padding: 14, marginBottom: 18,
          }}>
            <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 10 }}>Ваша оценка</div>
            {!hasNickname ? (
              <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>
                Укажите ник в{' '}
                <button onClick={onGoToProfile} className="press" style={{ background: 'none', border: 'none', color: 'var(--indigo)', cursor: 'pointer', padding: 0, fontSize: 13, fontWeight: 600 }}>
                  профиле
                </button>
                , чтобы оценивать города.
              </div>
            ) : isResident ? (
              <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>
                Вы житель этого города — оценивать его нельзя. Но скрин прислать можно 🙂
              </div>
            ) : ratedToday ? (
              <div style={{ fontSize: 13, color: 'var(--emerald)', display: 'flex', alignItems: 'center', gap: 6 }}>
                <Check size={15} /> Учтено. Следующее обновление — завтра.
              </div>
            ) : (
              <>
                {CRITERIA.map((c) => (
                  <div key={c.key} style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 4 }}>{c.label}</div>
                      <input
                        type="range" min="1" max="5" value={myRating[c.key]} className="slider-gold"
                        onChange={(e) => setMyRating((p) => ({ ...p, [c.key]: Number(e.target.value) }))}
                        style={{ width: '100%' }}
                      />
                    </div>
                    <div className="atlas-display" style={{ width: 20, textAlign: 'center', fontSize: 17, fontWeight: 700, color: 'var(--gold)' }}>
                      {myRating[c.key]}
                    </div>
                  </div>
                ))}
                <button
                  onClick={saveRating}
                  className="press"
                  style={{
                    width: '100%', marginTop: 4, padding: '11px 0', borderRadius: 12, border: 'none', cursor: 'pointer',
                    background: 'var(--gold)', color: '#1A1300', fontWeight: 700, fontSize: 14,
                  }}
                >
                  Сохранить оценку
                </button>
              </>
            )}
          </div>
        )}

        {isOwner && (
          <div style={{
            background: 'var(--indigo-soft)', border: '1px solid rgba(168,85,247,0.35)', borderRadius: 16, padding: 14, marginBottom: 18,
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 14, fontWeight: 700, marginBottom: 10, color: 'var(--indigo)' }}>
              <Sparkles size={15} /> Инструменты владельца
            </div>

            <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 6 }}>Скрины на проверке</div>
            {pending.length === 0 ? (
              <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 12 }}>Новых скринов на проверке нет.</div>
            ) : pending.map((s) => (
              <div key={s.id} style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
                <ShotThumb shot={s} onOpen={() => setLightbox({ shot: s, mode: 'moderate' })} />
                <div style={{ flex: 1, fontSize: 12, color: 'var(--text-muted)' }}>от {s.author}</div>
                <button onClick={() => moderateShot(s.id, true)} className="press" style={iconBtn('var(--emerald-soft)', 'var(--emerald)')}><Check size={15} /></button>
                <button onClick={() => moderateShot(s.id, false)} className="press" style={iconBtn('var(--red-soft)', 'var(--red)')}><X size={15} /></button>
              </div>
            ))}

            <button
              onClick={() => { setCuratorRequested(true); flash('Заявка отправлена инспектору'); }}
              className="press"
              disabled={curatorRequested}
              style={{
                width: '100%', marginTop: 6, padding: '11px 0', borderRadius: 12, border: '1px solid var(--indigo)', cursor: 'pointer',
                background: curatorRequested ? 'transparent' : 'var(--indigo)', color: curatorRequested ? 'var(--indigo)' : '#fff',
                fontWeight: 700, fontSize: 13,
              }}
            >
              {curatorRequested ? 'Заявка на переоценку отправлена' : 'Запросить оценку инспектора'}
            </button>
          </div>
        )}

        <SectionTitle icon={<MessageCircle size={15} />} title="Отзывы" count={t.reviews.length} />

        {!isOwner && (
          hasNickname ? (
            <div style={{ display: 'flex', gap: 8, marginBottom: 14 }}>
              <input
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder="Оставить отзыв о городе…"
                style={{
                  flex: 1, background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 12,
                  padding: '10px 12px', color: 'var(--text)', fontSize: 13, outline: 'none',
                }}
              />
              <button onClick={addComment} className="press" style={iconBtn('var(--surface)', 'var(--text)', true)}>
                <Send size={15} />
              </button>
            </div>
          ) : (
            <div style={{ fontSize: 12.5, color: 'var(--text-muted)', marginBottom: 14 }}>
              Укажите ник в{' '}
              <button onClick={onGoToProfile} className="press" style={{ background: 'none', border: 'none', color: 'var(--indigo)', cursor: 'pointer', padding: 0, fontSize: 12.5, fontWeight: 600 }}>
                профиле
              </button>
              , чтобы оставлять отзывы.
            </div>
          )
        )}

        <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginBottom: 10 }}>
          {t.reviews.length === 0 && (
            <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Пока нет отзывов — будьте первым, кто оценит этот город.</div>
          )}
          {t.reviews.map((r) => (
            <div key={r.id} style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 14, padding: 12 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
                <span style={{ fontSize: 13, fontWeight: 600 }}>{r.author}</span>
              </div>
              <div style={{ fontSize: 13, color: 'var(--text)', lineHeight: 1.4, marginBottom: 8 }}>{r.text}</div>

              {r.reply && (
                <div style={{
                  fontSize: 12, color: 'var(--text-muted)', background: 'var(--surface-2)', borderRadius: 10,
                  padding: '8px 10px', marginBottom: 8, borderLeft: '2px solid var(--indigo)',
                }}>
                  <b style={{ color: 'var(--indigo)' }}>{t.owner}: </b>{r.reply}
                </div>
              )}
              {isOwner && !r.reply && <ReplyBox onSend={(text) => reply(r.id, text)} />}

              <div style={{ display: 'flex', gap: 14, marginTop: 6 }}>
                <button onClick={() => react(r.id, 'like')} className="press" style={reactBtn(reacted[r.id] === 'like')}>
                  <ThumbsUp size={13} /> {r.likes}
                </button>
                <button onClick={() => react(r.id, 'dislike')} className="press" style={reactBtn(reacted[r.id] === 'dislike')}>
                  <ThumbsDown size={13} /> {r.dislikes}
                </button>
                <button onClick={() => react(r.id, 'report')} className="press" style={{ ...reactBtn(false), marginLeft: 'auto', color: reacted[r.id] === 'reported' ? 'var(--red)' : 'var(--text-muted)' }}>
                  <Flag size={13} /> {reacted[r.id] === 'reported' ? 'Отправлено' : 'Пожаловаться'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {showResidents && (
        <ResidentsModal
          residents={t.residents}
          ownerName={t.owner}
          isOwner={isOwner}
          onClose={() => setShowResidents(false)}
          newResident={newResident}
          setNewResident={setNewResident}
          onAdd={addResident}
          onRemove={removeResident}
        />
      )}

      {lightbox && (
        <Lightbox
          shot={lightbox.shot}
          mode={lightbox.mode}
          onClose={() => setLightbox(null)}
          onApprove={() => moderateShot(lightbox.shot.id, true)}
          onReject={() => moderateShot(lightbox.shot.id, false)}
        />
      )}

      {toast && (
        <div style={{
          position: 'fixed', bottom: 96, left: '50%', transform: 'translateX(-50%)',
          background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 999,
          padding: '9px 16px', fontSize: 12.5, color: 'var(--text)', boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
          zIndex: 50, whiteSpace: 'nowrap',
        }}>
          {toast}
        </div>
      )}
    </div>
  );
}

function ReplyBox({ onSend }) {
  const [val, setVal] = useState('');
  return (
    <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
      <input
        value={val}
        onChange={(e) => setVal(e.target.value)}
        placeholder="Ответить как основатель/мэр…"
        style={{
          flex: 1, background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 10,
          padding: '7px 10px', color: 'var(--text)', fontSize: 12.5, outline: 'none',
        }}
      />
      <button
        onClick={() => { if (val.trim()) { onSend(val.trim()); setVal(''); } }}
        className="press"
        style={{ ...iconBtn('var(--indigo-soft)', 'var(--indigo)'), width: 32, height: 32 }}
      >
        <Send size={13} />
      </button>
    </div>
  );
}

function ResidentsModal({ residents, ownerName, isOwner, onClose, newResident, setNewResident, onAdd, onRemove }) {
  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', zIndex: 60,
      display: 'flex', alignItems: 'flex-end', justifyContent: 'center',
    }} onClick={onClose}>
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: '100%', maxWidth: 448, background: 'var(--surface)', borderTopLeftRadius: 22, borderTopRightRadius: 22,
          border: '1px solid var(--border)', borderBottom: 'none', padding: 18, maxHeight: '70vh', overflowY: 'auto',
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
          <div className="atlas-display" style={{ fontSize: 16, fontWeight: 700 }}>Жители</div>
          <button onClick={onClose} className="press" style={iconBtn('var(--surface-2)', 'var(--text-muted)')}><X size={16} /></button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: isOwner ? 14 : 0 }}>
          {residents.length === 0 && <div style={{ fontSize: 12.5, color: 'var(--text-muted)' }}>Список жителей пуст.</div>}
          {residents.map((name) => {
            const canRemove = isOwner && name.trim().toLowerCase() !== ownerName.trim().toLowerCase();
            return (
              <div key={name} style={{
                display: 'flex', alignItems: 'center', gap: 10, background: 'var(--surface-2)', borderRadius: 12, padding: '9px 12px',
              }}>
                <User size={15} color="var(--text-muted)" />
                <span style={{ fontSize: 13.5, flex: 1 }}>{name}{name.trim().toLowerCase() === ownerName.trim().toLowerCase() ? ' · основатель/мэр' : ''}</span>
                {canRemove && (
                  <button onClick={() => onRemove(name)} className="press" style={{ background: 'transparent', border: 'none', color: 'var(--red)', cursor: 'pointer' }}>
                    <Trash2 size={14} />
                  </button>
                )}
              </div>
            );
          })}
        </div>

        {isOwner && (
          <div style={{ display: 'flex', gap: 8 }}>
            <input
              value={newResident}
              onChange={(e) => setNewResident(e.target.value)}
              placeholder="Ник игрока"
              style={{
                flex: 1, background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 10,
                padding: '9px 12px', color: 'var(--text)', fontSize: 13, outline: 'none',
              }}
            />
            <button onClick={onAdd} className="press" style={iconBtn('var(--indigo)', '#fff', true)}>
              <UserPlus size={15} />
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

function MainTabs({ tab, onChange }) {
  const items = [
    { key: 'recruit', label: 'Набор', icon: UserPlus },
    { key: 'map', label: 'Карта', icon: MapIcon },
    { key: 'rating', label: 'Рейтинг', icon: ListIcon },
  ];

  return (
    <div style={{ padding: '4px 16px 14px' }}>
      <div style={{
        background: 'var(--surface-2)', borderRadius: 12, padding: 3, display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: 2,
      }}>
        {items.map((it) => {
          const active = it.key === tab;
          const Icon = it.icon;
          return (
            <button
              key={it.key}
              onClick={() => onChange(it.key)}
              className="press"
              style={{
                display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 5,
                minWidth: 0, padding: '7px 7px', borderRadius: 999, fontSize: 12.5, fontWeight: active ? 700 : 600,
                border: 'none', cursor: 'pointer',
                background: active ? 'var(--indigo)' : 'transparent',
                color: active ? '#fff' : 'var(--text-muted)',
              }}
            >
              <Icon size={14} />
              <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{it.label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function BottomNav({ screen, onNavigate }) {
  const items = [
    { key: 'cities', icon: MapIcon, label: 'Города' },
    { key: 'profile', icon: User, label: 'Профиль' },
  ];
  return (
    <div style={{ position: 'fixed', bottom: 0, left: 0, right: 0, zIndex: 40, display: 'flex', justifyContent: 'center' }}>
      <div style={{
        width: '100%', maxWidth: 448, display: 'flex', background: 'rgba(20,23,28,0.92)',
        backdropFilter: 'blur(10px)', borderTop: '1px solid var(--border)', padding: '10px 6px 14px',
      }}>
        {items.map((it) => {
          const active = it.key === screen;
          return (
            <button
              key={it.key}
              onClick={() => onNavigate(it.key)}
              className="press"
              style={{
                flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3,
                color: active ? 'var(--indigo)' : 'var(--text-muted)', background: 'none', border: 'none', cursor: 'pointer',
              }}
            >
              <it.icon size={19} strokeWidth={active ? 2.4 : 2} />
              <span style={{ fontSize: 10.5, fontWeight: active ? 700 : 500 }}>{it.label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}


// ---------------------------------------------------------------------------
// Root
// ---------------------------------------------------------------------------
export default function CityRatingApp() {
  const tgUser = getTelegramUser();
  const [role, setRole] = useState('user');

  const [screen, setScreen] = useState('cities');
  const [mainTab, setMainTab] = useState('map');
  const [territoriesLoading, setTerritoriesLoading] = useState(true);
  const [territoriesError, setTerritoriesError] = useState(null);
  const [selectedId, setSelectedId] = useState(null);
  const [territories, setTerritories] = useState(TERRITORIES);
  const [profile, setProfile] = useState(() => ({ nickname: '', status: 'none' }));
  const [showAddTerritory, setShowAddTerritory] = useState(false);
  const [homeToast, setHomeToast] = useState(null);
  const [voxMapImage, setVoxMapImage] = useState(DEFAULT_VOX_MAP_IMAGE);

  const selected = territories.find((t) => t.id === selectedId);

  const refreshProfile = async () => {
    try {
      const initData = window.Telegram?.WebApp?.initData || '';
      if (!initData) return;
      const res = await fetch(`${API_BASE}/api/me`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        cache: 'no-store',
        body: JSON.stringify({ initData }),
      });
      const data = await res.json();
      if (!res.ok || !data?.ok) return;
      setRole(data.role || 'user');
      if (data.profile) {
        setProfile({
          nickname: data.profile.mc_nickname || '',
          status: data.profile.status || 'none',
        });
      } else if (data.role === 'inspector' || data.role === 'main_inspector') {
        setProfile({ nickname: '', status: 'verified' });
      }
    } catch (e) {
      console.error('Load profile/role error:', e);
    }
  };

  useEffect(() => {
    refreshProfile();
    const timer = setInterval(refreshProfile, 5000);
    return () => clearInterval(timer);
  }, []);

  async function loadVoxMap() {
    try {
      const res = await fetch(`${API_BASE}/api/map`, { cache: 'no-store' });
      const data = await res.json();
      if (res.ok && data?.ok && data.mapImage) setVoxMapImage(data.mapImage);
    } catch (e) { console.error('Load Vox map error:', e); }
  }

  async function loadTerritories() {
    try {
      setTerritoriesError(null);
      const res = await fetch(`${API_BASE}/api/territories`, { cache: 'no-store' });
      const data = await res.json();
      const rows = Array.isArray(data) ? data : data?.territories;
      if (!res.ok || !Array.isArray(rows)) {
        throw new Error(data?.error || `HTTP ${res.status}`);
      }
      const normalized = rows.map((row, index) => {
        const owner = row.owner ?? row.owner_input ?? 'Неизвестно';
        const coords = row.coords ?? '';
        return {
          id: row.id,
          name: row.name || 'Без названия',
          owner,
          coords,
          x: Number.isFinite(Number(row.x)) ? Number(row.x) : 50 + ((index * 17) % 30) - 15,
          y: Number.isFinite(Number(row.y)) ? Number(row.y) : 50 + ((index * 23) % 30) - 15,
          accent: row.accent || 'var(--indigo)',
          curator: Number(row.curator ?? 0),
          community: Number(row.community ?? 0),
          votes: Number(row.votes ?? 0),
          residents: Array.isArray(row.residents) ? row.residents : [owner],
          reviews: Array.isArray(row.reviews) ? row.reviews : [],
          screenshots: Array.isArray(row.screenshots) ? row.screenshots : [],
        };
      });
      setTerritories(normalized);
    } catch (error) {
      console.error('Load territories error:', error);
      setTerritoriesError(error?.message || 'Не удалось загрузить города');
    } finally {
      setTerritoriesLoading(false);
    }
  }

  useEffect(() => {
    loadTerritories();
    loadVoxMap();
    const onVisible = () => {
      if (document.visibilityState === 'visible') loadTerritories();
    };
    document.addEventListener('visibilitychange', onVisible);
    const timer = setInterval(loadTerritories, 15000);
    return () => {
      document.removeEventListener('visibilitychange', onVisible);
      clearInterval(timer);
    };
  }, []);

  function navigate(key) {
    setScreen(key);
    setSelectedId(null);
    if (key === 'cities') setMainTab('map');
  }

  function changeMainTab(tab) {
    setScreen('cities');
    setMainTab(tab);
    setSelectedId(null);
  }

  async function claimNickname(raw) {
    const nick = (raw || '').trim();
    if (!nick) return { ok: false, message: 'Введите ник.' };
    try {
      const initData = window.Telegram?.WebApp?.initData || '';
      if (!initData) return { ok: false, message: 'Откройте приложение через Telegram.' };
      const res = await fetch(`${API_BASE}/api/profile/claim`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nickname: nick, initData }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || !data.ok) return { ok: false, message: data.error || `HTTP ${res.status}` };
      setProfile((prev) => ({ ...prev, nickname: nick, status: 'pending' }));
      return { ok: true };
    } catch (e) {
      return { ok: false, message: e?.message || 'Не удалось отправить заявку.' };
    }
  }

  async function submitTerritoryRequest(data) {
    setShowAddTerritory(false);

    try {
      const tg = window.Telegram?.WebApp;
      const initData = tg?.initData || '';

      console.log('=== TERRITORY SUBMIT ===');
      console.log('API:', `${API_BASE}/api/territories`);
      console.log('Telegram WebApp exists:', !!tg);
      console.log('initData length:', initData.length);
      console.log('data:', data);

      if (!tg) {
        throw new Error('Telegram WebApp недоступен');
      }

      if (!initData) {
        throw new Error(
          'Telegram initData пустой. Откройте приложение через Telegram.'
        );
      }

      const res = await fetch(`${API_BASE}/api/territories`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...data,
          initData,
        }),
      });

      const responseText = await res.text();

      console.log('API status:', res.status);
      console.log('API response:', responseText);

      if (!res.ok) {
        let message = responseText;

        try {
          const json = JSON.parse(responseText);
          message = json.error || responseText;
        } catch {
          // Ответ не JSON — оставляем исходный текст.
        }

        throw new Error(
          `HTTP ${res.status}: ${message || 'пустой ответ'}`
        );
      }

      let result = null;

      try {
        result = JSON.parse(responseText);
      } catch {
        // Ничего страшного, если backend вернул обычный текст.
      }

      if (result && result.ok === false) {
        throw new Error(result.error || 'Backend вернул ошибку');
      }

      setHomeToast(
        'Заявка отправлена инспектору на подтверждение'
      );

    } catch (e) {
      console.error('Territory submit error:', e);

      setHomeToast(
        `Ошибка: ${e?.message || 'Неизвестная ошибка'}`
      );
    }

    setTimeout(() => {
      setHomeToast(null);
    }, 5000);
  }

  return (
    <div className="atlas-root" style={{ minHeight: '100vh', width: '100%' }}>
      <FontsAndTheme />
      <div style={{ maxWidth: 448, margin: '0 auto', position: 'relative' }}>
        {screen === 'profile' ? (
          <ProfileScreen profile={profile} claimNickname={claimNickname} role={role} tgUser={tgUser} refreshProfile={refreshProfile} />
        ) : selected ? (
          <TerritoryDetail
            base={selected}
            onBack={() => setSelectedId(null)}
            profile={profile}
            onGoToProfile={() => navigate('profile')}
          />
        ) : (
          <>
            <div style={{ padding: '18px 16px 10px', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 10 }}>
              <div>
                <div className="atlas-display" style={{ fontSize: 22, fontWeight: 700, letterSpacing: -0.3 }}>Multi-Punk</div>
                <div style={{ fontSize: 13, color: 'var(--text-muted)', marginTop: 2 }}>{territories.length} мест</div>
              </div>
              <button onClick={() => setShowAddTerritory(true)} className="press" style={{
                display: 'flex', alignItems: 'center', gap: 6, padding: '9px 14px', borderRadius: 999,
                border: 'none', cursor: 'pointer', background: 'var(--indigo)', color: '#fff', fontWeight: 700, fontSize: 13,
                flexShrink: 0, marginTop: 2,
              }}><Plus size={15} /> Добавить</button>
            </div>

            <MainTabs tab={mainTab} onChange={changeMainTab} />

            {territoriesError && (
              <div style={{ margin: '0 16px 10px', padding: '9px 12px', borderRadius: 10, background: 'var(--red-soft)', color: 'var(--red)', fontSize: 12 }}>
                Не удалось загрузить города: {territoriesError}
              </div>
            )}
            {territoriesLoading && (
              <div style={{ padding: '14px 16px', color: 'var(--text-muted)', fontSize: 12.5 }}>Загрузка городов…</div>
            )}

            {mainTab === 'recruit' ? (
              <div style={{ padding: '0 16px 90px' }}>
                <div style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 16, padding: 18 }}>
                  <div className="atlas-display" style={{ fontSize: 17, fontWeight: 700, marginBottom: 6 }}>Набор в город</div>
                  <div style={{ fontSize: 13, lineHeight: 1.5, color: 'var(--text-muted)' }}>
                    Здесь будет раздел набора жителей в города. Города и профиль остаются отдельными разделами нижней навигации.
                  </div>
                </div>
              </div>
            ) : (
              <HomeScreen
                territories={territories}
                onSelect={setSelectedId}
                onAddTerritory={() => setShowAddTerritory(true)}
                mode={mainTab === 'rating' ? 'list' : 'map'}
                mapImage={voxMapImage}
                onMapToast={(message) => {
                  setHomeToast(message);
                  setTimeout(() => setHomeToast(null), 2200);
                }}
              />
            )}
          </>
        )}
        <BottomNav screen={screen} onNavigate={navigate} />

        {showAddTerritory && (
          <AddTerritoryModal onClose={() => setShowAddTerritory(false)} onSubmit={submitTerritoryRequest} />
        )}

        {homeToast && (
          <div style={{
            position: 'fixed', bottom: 96, left: '50%', transform: 'translateX(-50%)',
            background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 999,
            padding: '9px 16px', fontSize: 12.5, color: 'var(--text)', boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
            zIndex: 90, whiteSpace: 'nowrap',
          }}>
            {homeToast}
          </div>
        )}
      </div>
    </div>
  );
}
